INSERT INTO faqs (faq_id, category, question, answer, updated_at) VALUES
  (1, 'shipping', 'How long does shipping take?', 'Standard shipping takes 3-5 business days within the continental US. Frozen and perishable orders ship via overnight or 2-day air with dry ice. Expedited options are available at checkout. B2B foodservice customers on contract terms have weekly scheduled delivery windows; see your account manager for the schedule.', CURRENT_TIMESTAMP()),
  (2, 'shipping', 'Do you ship internationally?', 'We currently ship to the continental US, Canada, and Mexico. Hawaii and Alaska are supported for non-perishable items only. International shipments to Canada and Mexico require additional 2-4 business days. We do not ship frozen items internationally at this time.', CURRENT_TIMESTAMP()),
  (3, 'shipping', 'Do you offer free shipping?', 'Free standard shipping is included on B2C orders over $75. B2B foodservice customers receive free shipping based on their contracted minimum order quantity (typically $250+). Expedited and frozen-overnight shipping carry their actual shipping cost.', CURRENT_TIMESTAMP()),
  (4, 'returns', 'What is your return policy?', 'Non-perishable items can be returned within 30 days for a full refund. Frozen and perishable items cannot be returned for food-safety reasons but are eligible for replacement or refund if the order arrived damaged, mis-packed, or after the printed thaw date. Initiate returns via your order history or contact support.', CURRENT_TIMESTAMP()),
  (5, 'returns', 'How do I return a damaged frozen item?', 'Take a photo of the damage (packaging, thermal pack, or product) within 24 hours of delivery and submit it via the support form. We will issue a replacement on your next delivery or a refund — your choice. Do not ship perishables back to us.', CURRENT_TIMESTAMP()),
  (6, 'returns', 'How are refunds processed?', 'Approved refunds are issued to the original payment method within 5-7 business days. B2B accounts on net-payment terms receive a credit memo applied to the next invoice. Replacement items typically ship same-day or next-day.', CURRENT_TIMESTAMP()),
  (7, 'account', 'How do I update my shipping address?', 'Sign in to your account, navigate to Account → Addresses, and edit the primary shipping address. Address changes apply to future orders only — in-flight orders use the address active at the time of placement. B2B accounts should coordinate with their account manager for delivery-window changes.', CURRENT_TIMESTAMP()),
  (8, 'account', 'Can I have multiple shipping locations on a B2B account?', 'Yes. B2B foodservice accounts can configure unlimited delivery locations under a single account, each with its own delivery window and contact. Add new locations under Account → B2B → Locations or ask your account manager to set them up.', CURRENT_TIMESTAMP()),
  (9, 'account', 'How do I reset my password?', 'Click ''Forgot Password'' on the sign-in page and enter your email. A reset link is sent within a few minutes. Links expire after 30 minutes for security. If you don''t receive an email, check spam or contact support.', CURRENT_TIMESTAMP()),
  (10, 'products', 'Are your products kosher?', 'Many of our non-meat products carry kosher certification — look for the certification symbol on each product page. The whipped topping, decorating gels, and several pastry items are kosher-certified by OU. Our meat and pizza items are not kosher.', CURRENT_TIMESTAMP()),
  (11, 'products', 'Which products are gluten-free?', 'Our gluten-free product family includes the Triple Chocolate Mousse Cake, Gluten-Free Chocolate Chip Cookies, and Sugar-Free Vanilla Frozen Dessert. Each product page shows the full allergen profile. We caution that our facilities also process wheat, so individuals with severe celiac sensitivity should evaluate based on their tolerance.', CURRENT_TIMESTAMP()),
  (12, 'products', 'Do you have vegan options?', 'Yes — we carry a growing plant-based portfolio. The Vegan Chocolate Cake, Vegan Banana Walnut Muffin Batter, and several Heritage Bakehouse items are fully vegan. All vegan products are flagged on their product pages and discoverable via category ''Plant-Based''.', CURRENT_TIMESTAMP()),
  (13, 'products', 'How should I store frozen items?', 'Keep frozen items at 0°F (-18°C) until ready to use. Once thawed, follow the product-specific thaw-and-serve instructions on the package; most products are good 3-5 days refrigerated after thawing. Do not refreeze thawed items.', CURRENT_TIMESTAMP()),
  (14, 'b2b', 'How do I open a B2B foodservice account?', 'Apply via the ''B2B Account'' link in the site footer. We require a business tax ID, business address, and approximate monthly volume. Most applications are approved within 2 business days. Approved accounts get net-30 payment terms by default; net-60 is available based on credit history.', CURRENT_TIMESTAMP()),
  (15, 'b2b', 'What is the minimum B2B order size?', 'Minimum order size varies by delivery zone — typically $150-$250 for foodservice delivery, with reduced minimums for pickup orders. Your account manager can confirm your exact minimum and consolidation thresholds.', CURRENT_TIMESTAMP()),
  (16, 'b2b', 'How are B2B credit limits set?', 'Initial credit limits are based on business tax ID review and a soft credit check. Limits are reviewed quarterly and can be increased based on payment history. Speak with your account manager to request a credit limit review.', CURRENT_TIMESTAMP()),
  (17, 'payment', 'What payment methods do you accept?', 'B2C: Visa, Mastercard, American Express, Discover, Apple Pay, and Google Pay. B2B: net-30 (default), net-60 (upon credit approval), wire transfer, and ACH. Credit card payments on B2B invoices incur a 2.5% convenience fee.', CURRENT_TIMESTAMP()),
  (18, 'payment', 'Why was my card declined?', 'Common reasons include insufficient funds, incorrect billing address, expired card, or your bank flagging the transaction. The exact decline reason is shown at checkout. Contact your card issuer to authorize the charge, then retry.', CURRENT_TIMESTAMP());
